SELECT ?point ?label ?ts WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  ?label a rdfs:Label .
  FILTER(?label = "DataCenter_bot_ZN_6" || ?label = "Perimeter_top_ZN_3")
  OPTIONAL { ?zone ref:hasExternalReference / ref:hasTimeseriesId ?ts }
}

SELECT ?z (SAMPLE(?label) as ?label) ?class WHERE {
  ?z rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "ZN_6") || CONTAINS(LCASE(?label), "ZN_3"))
  GROUP BY ?z
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  FILTER(CONTAINS(?label, "ZN_") )
}

